package glitch

import data.glitch_lib

password_field_patterns := [
    "password", "passwd", "pwd", "secret", "credentials", "auth",
    "authentication", "login_pass", "admin_password", "root_password",
    "master_password", "user_password", "db_password", "database_password",
    "service_password", "api_password", "token", "api_key", "access_key",
    "secret_key", "private_key", "passphrase"
]

default_passwords := [
    "admin", "password", "123456", "default", "root", "guest",
    "test", "changeme", "12345678", "qwerty", "letmein"
]

is_password_field(name) {
    field := password_field_patterns[_]
    regex.match(sprintf(".*%s.*", [field]), lower(name))
}

is_hardcoded_string(value) {
    value.ir_type == "String"
    value.value != ""
    not is_secure_reference(value.value)
}

is_secure_reference(str) {
    regex.match("\\$\\{.*\\}", str)
} else {
    regex.match("\\{\\{.*\\}\\}", str)
} else {
    regex.match(".*vault.*", lower(str))
} else {
    regex.match(".*secret.*manager.*", lower(str))
} else {
    regex.match(".*parameter.*store.*", lower(str))
} else {
    regex.match(".*env\\.*", lower(str))
} else {
    regex.match(".*file\\(.*", lower(str))
}

has_low_entropy(value) {
    value.ir_type == "String"
    count(value.value) > 0
    count(value.value) < 16
    regex.match("^[a-zA-Z0-9]+$", value.value)
}

is_default_password(value) {
    value.ir_type == "String"
    default := default_passwords[_]
    lower(value.value) == default
}

is_base64_like(value) {
    value.ir_type == "String"
    regex.match("^[A-Za-z0-9+/]+={0,2}$", value.value)
    count(value.value) > 8
    count(value.value) % 4 == 0
}

check_value_for_hardcoded_password(value) {
    is_hardcoded_string(value)
    has_low_entropy(value)
} else {
    is_hardcoded_string(value)
    is_default_password(value)
} else {
    is_hardcoded_string(value)
    is_base64_like(value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    is_password_field(attr.name)
    check_value_for_hardcoded_password(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Credentials should not be hardcoded and should be retrieved from secure secret management systems. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    is_password_field(var.name)
    check_value_for_hardcoded_password(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded password - Credentials should not be hardcoded and should be retrieved from secure secret management systems. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_password_field(attr.name)
    check_value_for_hardcoded_password(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Credentials should not be hardcoded and should be retrieved from secure secret management systems. (CWE-259)"
    }
