package glitch

import data.glitch_lib

password_field_patterns := [
    "password", "passwd", "pwd", "secret", "credentials", "auth",
    "authentication", "login_pass", "admin_password", "root_password",
    "master_password", "user_password", "db_password", "database_password",
    "service_password", "api_password", "token", "api_key", "access_key",
    "secret_key", "private_key", "passphrase"
]

default_password_list := [
    "admin", "password", "123456", "default", "root", "guest",
    "test", "changeme", "12345678", "qwerty", "letmein", "passw0rd"
]

is_password_field(name) {
    field := password_field_patterns[_]
    regex.match(sprintf("(?i).*%s.*", [field]), name)
}

is_hardcoded_value(value) {
    value.ir_type == "String"
    value.value != ""
    not is_secure_reference(value.value)
}

is_secure_reference(str) {
    regex.match("^[a-zA-Z_][a-zA-Z0-9_]*$", str)
    not regex.match("^[0-9]+$", str)
    not regex.match("^[a-fA-F0-9]{32,}$", str)
} else {
    regex.match("\\$\\{.*\\}", str)
} else {
    regex.match("\\{\\{.*\\}\\}", str)
}

has_low_entropy(value) {
    is_hardcoded_value(value)
    count(value.value) > 0
    count(value.value) < 16
    not regex.match("[A-Za-z].*[0-9].*[^A-Za-z0-9]|[0-9].*[A-Za-z].*[^A-Za-z0-9]|[A-Za-z].*[^A-Za-z0-9].*[0-9]|[0-9].*[^A-Za-z0-9].*[A-Za-z]|[^A-Za-z0-9].*[A-Za-z].*[0-9]|[^A-Za-z0-9].*[0-9].*[A-Za-z]", value.value)
}

is_default_password(value) {
    is_hardcoded_value(value)
    dp := default_password_list[_]
    lower(value.value) == dp
}

is_base64_like(value) {
    is_hardcoded_value(value)
    regex.match("^[A-Za-z0-9+/]+={0,2}$", value.value)
    count(value.value) > 8
    count(value.value) % 4 == 0
}

is_hash_like_password(value) {
    is_hardcoded_value(value)
    regex.match("^\\$[0-9a-zA-Z]+\\$", value.value)
}

suspicious_password(value) {
    is_hardcoded_value(value)
} else {
    is_hardcoded_value(value)
    has_low_entropy(value)
} else {
    is_hardcoded_value(value)
    is_default_password(value)
} else {
    is_hardcoded_value(value)
    is_base64_like(value)
} else {
    is_hardcoded_value(value)
    is_hash_like_password(value)
}

find_hash_entries(node) = entries {
    node.ir_type == "Hash"
    entries = [e | e := node.value[_]]
} else = [] {
    true
}

find_array_entries(node) = entries {
    node.ir_type == "Array"
    entries = [e | e := node.value[_]]
} else = [] {
    true
}

check_nested_value(node, parent_name) = results {
    results := {r |
        entries := find_hash_entries(node)
        entry := entries[_]
        key_name := entry.key.value
        full_name := sprintf("%s.%s", [parent_name, key_name])
        is_password_field(full_name)
        suspicious_password(entry.value)
        r := {"name": full_name, "value": entry.value, "key_name": key_name}
    }
}

check_array_items(node, parent_name) = results {
    results := {r |
        items := find_array_entries(node)
        item := items[_]
        item.ir_type == "Hash"
        hash_entries := find_hash_entries(item)
        entry := hash_entries[_]
        key_name := entry.key.value
        is_password_field(key_name)
        suspicious_password(entry.value)
        r := {"name": key_name, "value": entry.value, "key_name": key_name}
    }
}

