password_field_patterns := ["password", "passwd", "pwd", "secret", "credentials", "auth", "authentication", "login_pass", "admin_password", "root_password", "master_password", "user_password", "db_password", "database_password", "service_password", "api_password", "token", "api_key", "access_key", "secret_key", "private_key", "passphrase", "key"]

default_passwords := ["admin", "password", "123456", "default", "root", "guest", "test", "changeme", "12345678", "qwerty", "letmein", "passw0rd"]

is_password_field(name) {
    field := password_field_patterns[_]
    regex.match(sprintf("(?i).*%s.*", [field]), name)
}

is_hardcoded_string(value) {
    value.ir_type == "String"
    value.value != ""
    not is_secure_reference(value.value)
}

is_secure_reference(str) {
    startswith(str, "${")
    endswith(str, "}")
} else {
    startswith(str, "{{")
    endswith(str, "}}")
} else {
    startswith(str, "$")
} else {
    regex.match(".*\\bvar\\.", str)
} else {
    regex.match(".*\\bdata\\.", str)
} else {
    regex.match(".*\\bmodule\\.", str)
} else {
    regex.match(".*\\bvault\\b.*", lower(str))
} else {
    regex.match(".*\\blookup\\s*\\(", lower(str))
} else {
    regex.match(".*\\bsecret\\b.*", lower(str))
}

is_default_password(value) {
    dp := default_passwords[_]
    lower(value.value) == dp
}

is_base64_like(value) {
    regex.match("^[A-Za-z0-9+/]+={0,2}$", value.value)
    count(value.value) >= 8
    count(value.value) % 4 == 0
}

is_hash_like_password(value) {
    regex.match("^\\$[0-9a-zA-Z]+\\$", value.value)
}

suspicious_password(value) {
    is_hardcoded_string(value)
} else {
    is_hardcoded_string(value)
    is_base64_like(value)
} else {
    is_hardcoded_string(value)
    is_hash_like_password(value)
}

extract_key_value_from_string(str) = [key, val] {
    idx := indexof(str, "=")
    idx > 0
    key := substring(str, 0, idx)
    val := substring(str, idx + 1, count(str))
}

is_keyvalue_type(node) {
    node.ir_type == "Variable"
} else {
    node.ir_type == "Attribute"
}

